/**
 * Persists the VS Code bridge settings (pairing) and its live connection
 * status in chrome.storage.local, so the popup can show them and the
 * background service worker — which owns the socket — can read them.
 */

import { DEFAULT_BRIDGE_PORT } from "@protocol";
import { ChromeStorage } from "./chromeStorage.service";

export const STORAGE_KEY_BRIDGE_SETTINGS = "bridge_settings";
export const STORAGE_KEY_BRIDGE_STATUS = "bridge_status";

export interface BridgeSettings {
  enabled: boolean;
  port: number;
  /** Pairing secret generated by the VS Code extension. */
  token: string;
}

export const DEFAULT_BRIDGE_SETTINGS: BridgeSettings = {
  enabled: false,
  port: DEFAULT_BRIDGE_PORT,
  token: "",
};

export type BridgeConnectionState =
  | "off" // not paired / disabled
  | "connecting" // paired, waiting for VS Code to be reachable
  | "connected"
  | "unauthorized" // VS Code rejected our proof
  | "untrusted" // whatever is on the port could not prove it knows the token
  | "incompatible"; // protocol version mismatch

const CONNECTION_STATES: readonly BridgeConnectionState[] = [
  "off",
  "connecting",
  "connected",
  "unauthorized",
  "untrusted",
  "incompatible",
];

function sanitizeSettings(stored: Partial<BridgeSettings>): BridgeSettings {
  const token = typeof stored.token === "string" ? stored.token : "";
  return {
    enabled: stored.enabled === true && token !== "",
    port:
      typeof stored.port === "number" && Number.isInteger(stored.port)
        ? stored.port
        : DEFAULT_BRIDGE_SETTINGS.port,
    token,
  };
}

export const BridgeSettingsService = {
  async getSettings(): Promise<BridgeSettings> {
    const storageResult = await ChromeStorage.storageGet(
      STORAGE_KEY_BRIDGE_SETTINGS,
    );
    const stored = storageResult[STORAGE_KEY_BRIDGE_SETTINGS] as
      Partial<BridgeSettings> | undefined;
    return stored ? sanitizeSettings(stored) : DEFAULT_BRIDGE_SETTINGS;
  },

  async setSettings(settings: BridgeSettings): Promise<void> {
    await ChromeStorage.storageSet({ [STORAGE_KEY_BRIDGE_SETTINGS]: settings });
  },

  async getState(): Promise<BridgeConnectionState> {
    const storageResult = await ChromeStorage.storageGet(
      STORAGE_KEY_BRIDGE_STATUS,
    );
    const stored = storageResult[STORAGE_KEY_BRIDGE_STATUS];
    return CONNECTION_STATES.find((state) => state === stored) ?? "off";
  },

  async setState(state: BridgeConnectionState): Promise<void> {
    await ChromeStorage.storageSet({ [STORAGE_KEY_BRIDGE_STATUS]: state });
  },
};
